async function identity(req,env){const id=req.headers.get('oai-authenticated-user-id');if(!id)throw new ApiError('ChatGPT hisobingiz bilan kiring.',401);let user=await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(id).first();if(!user){let name=req.headers.get('oai-authenticated-user-full-name')||'Firdavs';try{if(req.headers.get('oai-authenticated-user-full-name-encoding')==='percent-encoded-utf-8')name=decodeURIComponent(name)}catch{}await env.DB.batch([env.DB.prepare('INSERT OR IGNORE INTO users(id,name,created) VALUES(?,?,?)').bind(id,name.slice(0,32),Date.now()),env.DB.prepare("INSERT OR IGNORE INTO configuration(key,value) VALUES('owner',?)").bind(id)]);user=await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(id).first()}const owner=await env.DB.prepare("SELECT value FROM configuration WHERE key='owner'").first();return {...user,role:owner?.value===id?'admin':'user'}}
async function bootstrap(user,env){const rows=await env.DB.prepare('SELECT pid,coins FROM accepted WHERE uid=?').bind(user.id).all();const submissions=await env.DB.prepare('SELECT id,pid,language,status,detail,passed,total,created FROM submissions WHERE uid=? ORDER BY created DESC LIMIT 1000').bind(user.id).all();const personal=await env.DB.prepare('SELECT body FROM personal WHERE uid=?').bind(user.id).first();const customs=await env.DB.prepare('SELECT id,body FROM custom_problems ORDER BY id').all();const activity={};for(const s of submissions.results){const day=new Date(s.created).toLocaleDateString('en-CA',{timeZone:'Asia/Tashkent'});activity[day]=(activity[day]||0)+1}let local={};try{local=JSON.parse(personal?.body||'{}')}catch{}return {user:{id:user.id,role:user.role},state:{profile:{name:user.name,bio:user.bio,avatar:user.avatar},saved:local.saved||[],drafts:local.drafts||{},solved:rows.results.map(r=>r.pid),attempts:submissions.results.map(r=>({id:r.pid,submission:r.id,time:r.created,ok:r.status==='Accepted',count:r.passed,total:r.total,status:r.status,language:r.language,detail:r.detail})),activity,custom:customs.results.map(r=>(({tests,...safe})=>({...safe,id:r.id+1000,custom:true}))(JSON.parse(r.body)))},coins:rows.results.reduce((s,r)=>s+r.coins,0)}}
async function problem(env,id){if(id<=1000)return PUBLIC_PROBLEMS[id-1];const r=await env.DB.prepare('SELECT body FROM custom_problems WHERE id=?').bind(id-1000).first();return r?{...JSON.parse(r.body),id}:null}
async function testsFor(env,id){if(id<=1000)return HIDDEN_TESTS[id];const p=await problem(env,id);return p?.tests||[]}
async function body(req){if(Number(req.headers.get('Content-Length')||0)>180000)throw new ApiError('So‘rov juda katta.',413);const raw=await req.text();if(raw.length>180000)throw new ApiError('So‘rov juda katta.',413);try{return JSON.parse(raw)}catch{throw new ApiError('JSON formati noto‘g‘ri.')}}
async function api(req,env){try{const url=new URL(req.url),path=url.pathname;if(req.method==='POST'){const origin=req.headers.get('Origin');if(origin&&origin!==url.origin)throw new ApiError('Origin mos emas.',403);if(!req.headers.get('Content-Type')?.startsWith('application/json'))throw new ApiError('JSON yuboring.',415)}if(req.method==='GET'&&path==='/api/diagnostics'){let database=false;try{await env.DB.prepare('SELECT COUNT(*) AS n FROM users').first();database=true}catch{}const results={};for(const language of ['cpp','py']){try{const r=await execute(env,language==='cpp'?'#include <iostream>\nint main(){long long a,b;std::cin>>a>>b;std::cout<<a+b;}':'a,b=map(int,input().split()); print(a+b)',language,'4 7');results[language]={ok:r.ok&&normalize(r.output)==='11',status:r.status||'Executed',detail:r.detail||r.output}}catch(e){results[language]={ok:false,error:e.message}}}return json({database,results})}const u=await identity(req,env);
 if(req.method==='GET'&&path==='/api/bootstrap')return json(await bootstrap(u,env));
 if(req.method==='GET'&&path==='/api/judge-health'){try{if(env.JUDGE0_URL)return json({provider:'Judge0',ready:true,configured:true});const list=await compilerList();return json({provider:'Wandbox',ready:true,compilers:list.filter(x=>['C++','Python'].includes(x.language)).map(x=>({name:x.name,language:x.language}))})}catch(e){return json({provider:'Wandbox',ready:false,error:e.message},503)}}
 if(req.method==='GET'&&path==='/api/ranking'){const rows=await env.DB.prepare('SELECT u.name,u.avatar,COUNT(a.pid) solved,COALESCE(SUM(a.coins),0) coins FROM users u LEFT JOIN accepted a ON a.uid=u.id GROUP BY u.id ORDER BY solved DESC,coins DESC,u.name LIMIT 100').all();return json(rows.results)}
 if(req.method==='GET'&&path==='/api/users'){if(u.role!=='admin')throw new ApiError('Admin huquqi kerak.',403);return json((await env.DB.prepare('SELECT id,name,created FROM users ORDER BY created').all()).results)}
 if(req.method==='POST'&&path==='/api/state'){const d=await body(req),p=d.profile;if(!p||typeof p.name!=='string'||!p.name.trim()||p.name.length>32||typeof p.bio!=='string'||p.bio.length>400||typeof p.avatar!=='string'||p.avatar.length>80000||(p.avatar&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(p.avatar)))throw new ApiError('Profil formati noto‘g‘ri.');const saved=Array.isArray(d.saved)?d.saved.filter(x=>Number.isInteger(x)&&x>0).slice(0,3000):[];const drafts={};if(d.drafts&&typeof d.drafts==='object')for(const [k,v] of Object.entries(d.drafts).slice(0,200)){if(/^\d+$/.test(k)&&v&&typeof v.text==='string'&&['cpp','py'].includes(v.language))drafts[k]={text:v.text.slice(0,30000),language:v.language}}const personal=JSON.stringify({saved,drafts});if(personal.length>120000)throw new ApiError('Qoralamalar hajmi katta. Bir qismini faylga yuklab saqlang.');await env.DB.batch([env.DB.prepare('UPDATE users SET name=?,bio=?,avatar=? WHERE id=?').bind(p.name.trim(),p.bio,p.avatar,u.id),env.DB.prepare('INSERT INTO personal(uid,body) VALUES(?,?) ON CONFLICT(uid) DO UPDATE SET body=excluded.body').bind(u.id,personal)]);return json({ok:true})}
 if(req.method==='POST'&&path==='/api/submit'){const d=await body(req),pid=Number(d.pid),p=await problem(env,pid);if(!p||typeof d.code!=='string'||!d.code.trim()||d.code.length>30000||!['cpp','py'].includes(d.language))throw new ApiError('Masala, til yoki kod noto‘g‘ri.');const recent=await env.DB.prepare('SELECT created FROM submissions WHERE uid=? ORDER BY created DESC LIMIT 1').bind(u.id).first();if(recent&&Date.now()-recent.created<15000)throw new ApiError('Yangi yechimni 15 soniyadan keyin yuboring.',429);const pending=await env.DB.prepare("SELECT id FROM submissions WHERE uid=? AND status IN ('Queued','Running') AND created>?").bind(u.id,Date.now()-120000).first();if(pending)throw new ApiError('Oldingi yechim hali tekshirilmoqda. Urinishlar bo‘limidan davom ettiring.',409);const id=crypto.randomUUID(),tests=await testsFor(env,pid);if(!tests.length)throw new ApiError('Masala uchun testlar yo‘q.',409);await env.DB.prepare('INSERT INTO submissions(id,uid,pid,language,code,status,total,created) VALUES(?,?,?,?,?,?,?,?)').bind(id,u.id,pid,d.language,d.code,'Queued',tests.length,Date.now()).run();return json({id,status:'Queued',passed:0,total:tests.length})}
 if(req.method==='POST'&&path==='/api/judge-step'){const d=await body(req);let s=await env.DB.prepare('SELECT * FROM submissions WHERE id=? AND uid=?').bind(String(d.id),u.id).first();if(!s)throw new ApiError('Urinish topilmadi.',404);if(!['Queued','Running','Service Unavailable'].includes(s.status))return json({id:s.id,status:s.status,passed:s.passed,total:s.total,detail:s.detail});if(s.status==='Running'){const lockAge=Date.now()-Number(s.detail||0);if(lockAge<30000)throw new ApiError('Bu urinishning testi allaqachon bajarilmoqda.',409)}const claim=await env.DB.prepare('UPDATE submissions SET status=?,detail=? WHERE id=? AND status=? AND detail=?').bind('Running',String(Date.now()),s.id,s.status,s.detail).run();if(!claim.meta.changes)throw new ApiError('Urinish band.',409);const tests=await testsFor(env,s.pid);let status='Queued',detail='',passed=s.passed;try{const r=await execute(env,s.code,s.language,tests[passed].input);if(!r.ok){status=r.status;detail=r.detail}else if(normalize(r.output)!==normalize(tests[passed].output)){status='Wrong Answer';detail=(passed+1)+'-testda natija mos kelmadi. Sizning chiqishingiz: '+String(r.output).slice(0,2000)}else{passed++;if(passed===tests.length)status='Accepted'}}catch(e){status='Service Unavailable';detail=e.name==='TimeoutError'?'Kompilyatsiya xizmati vaqtida javob bermadi.':e.message}await env.DB.prepare('UPDATE submissions SET status=?,detail=?,passed=? WHERE id=?').bind(status,detail,passed,s.id).run();if(status==='Accepted'){const p=await problem(env,s.pid);await env.DB.prepare('INSERT OR IGNORE INTO accepted(key,uid,pid,coins,created) VALUES(?,?,?,?,?)').bind(u.id+':'+s.pid,u.id,s.pid,(p.level||1)*5,Date.now()).run()}return json({id:s.id,status,passed,total:s.total,detail})}
 if(req.method==='POST'&&path==='/api/problems'){if(u.role!=='admin')throw new ApiError('Admin huquqi kerak.',403);const d=await body(req);for(const k of ['title','category','statement','input','output','hint'])if(typeof d[k]!=='string'||!d[k].trim()||d[k].length>6000)throw new ApiError('Barcha matn maydonlarini to‘ldiring.');if(![1,2,3].includes(d.level)||!Array.isArray(d.samples)||!d.samples.length||!Array.isArray(d.tests)||!d.tests.length||d.tests.length>30||d.samples.concat(d.tests).some(t=>typeof t.input!=='string'||typeof t.output!=='string'))throw new ApiError('Namunalar va testlar formati noto‘g‘ri.');d.practice=d.tests.slice(0,4);const r=await env.DB.prepare('INSERT INTO custom_problems(body) VALUES(?)').bind(JSON.stringify(d)).run();return json({id:Number(r.meta.last_row_id)+1000})}
 throw new ApiError('Sahifa topilmadi.',404)
 }catch(e){console.error(e.message);return json({error:e.message||'Server xatosi'},e.status||500)}}
export default {async fetch(req,env){if(new URL(req.url).pathname.startsWith('/api/'))return api(req,env);return new Response(HTML,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'same-origin'}})}};
